import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);
        String[] aLine = br.readLine().split(" ");
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(aLine[i]);
        }

        List<Integer> part1 = new ArrayList<>();
        List<Integer> part2 = new ArrayList<>();
        int max_mod = 0;

        int half = (n / 2) + (n % 2);
        int limit1 = 1 << half;
        int limit2 = 1 << (n / 2);

        // Generate all subset sums for first half
        for (int subset_mask = 0; subset_mask < limit1; subset_mask++) {
            int sum_value = 0;
            int current_mask = subset_mask;
            for (int _ = 0; _ < 20; _++) {
                if ((current_mask & 1) == 1 && _ < half) {
                    sum_value += a[_];
                }
                current_mask >>= 1;
            }
            part1.add(sum_value % m);
        }
        Collections.sort(part1);

        // Generate all subset sums for second half
        for (int subset_mask = 0; subset_mask < limit2; subset_mask++) {
            int sum_value = 0;
            int current_mask = subset_mask;
            for (int _ = 0; _ < 20; _++) {
                int index = _ + half;
                if ((current_mask & 1) == 1 && index < n) {
                    sum_value += a[index];
                }
                current_mask >>= 1;
            }
            sum_value %= m;

            int target = m - sum_value - 1;
            int idx = Collections.binarySearch(part1, target);
            if (idx < 0) {
                idx = -idx - 1;
            }
            int candidate;
            if (idx < part1.size()) {
                candidate = part1.get(idx);
                if (candidate > target && idx - 1 >= 0) {
                    candidate = part1.get(idx - 1);
                }
            } else {
                candidate = part1.get(part1.size() - 1);
            }
            max_mod = Math.max(max_mod, Math.max((sum_value + candidate) % m, (sum_value + part1.get(part1.size() - 1)) % m));
        }

        System.out.println(max_mod);
    }
}
